create table if not exists public.checkout_intents (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_id uuid references public.plans(id) on delete set null,type text not null check(type in ('subscription','one_time','ad_campaign','promotion')),billing_interval text check(billing_interval in ('free','monthly','yearly')),amount_minor bigint not null default 0 check(amount_minor>=0),currency char(3) not null default 'USD',provider text,provider_checkout_id text,status text not null default 'created' check(status in ('created','pending','completed','failed','cancelled','expired')),expires_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists checkout_intents_user_idx on public.checkout_intents(user_id,created_at desc); create unique index if not exists platform_revenue_order_commission_uniq on public.platform_revenue(order_id) where source_type='marketplace_commission' and order_id is not null; create or replace function public.recognize_order_platform_commission() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status='paid' and new.platform_commission>0 then insert into public.platform_revenue(source_type,order_id,amount_minor,currency,status,description,recognized_at) values('marketplace_commission',new.id,round(new.platform_commission*100)::bigint,new.currency,'recognized','Comisión de Credi Marketplace por orden pagada',now()) on conflict (order_id) where source_type='marketplace_commission' and order_id is not null do nothing; end if; return new; end; $$; drop trigger if exists trg_recognize_order_platform_commission on public.orders; create trigger trg_recognize_order_platform_commission after insert or update of status,platform_commission on public.orders for each row execute function public.recognize_order_platform_commission(); alter table public.checkout_intents enable row level security; create policy checkout_intents_owner_read on public.checkout_intents for select using(user_id=auth.uid()); grant select on public.checkout_intents to authenticated; revoke all on public.platform_revenue from public,anon,authenticated; revoke all on function public.recognize_order_platform_commission() from public,anon,authenticated;
